class Solution:
    def strobogrammaticInRange(self, low: str, high: str) -> int:
        def gen(n):
            if n == 0: return ['']
            if n == 1: return ['0', '1', '8']
            inner = gen(n - 2)
            res = []
            for a, b in [('1','1'),('6','9'),('8','8'),('9','6'),('0','0')]:
                for s in inner:
                    res.append(a + s + b)
            return res
        ans = 0
        for n in range(len(low), len(high) + 1):
            for s in gen(n):
                if s[0] != '0' and low <= s <= high:
                    ans += 1
                elif n == 1 and low <= s <= high:
                    ans += 1
        return ans

