class Solution {
public:
    int strobogrammaticInRange(string low, string high) {
        long long ans = 0;
        vector<pair<char,char>> pairs = {{'1','1'},{'6','9'},{'8','8'},{'9','6'},{'0','0'}};
        vector<string> cur = {""};
        bool oddTurn = false;
        for (int n = 1; n <= (int)high.size(); n++) {
            vector<string> nxt;
            if (oddTurn) {
                for (string mid : {string("0"), string("1"), string("8")})
                    for (auto& p : pairs)
                        if (!(p.first=='0' && n==1))
                            nxt.push_back(p.first + mid + p.second);
            } else {
                for (auto& p : pairs)
                    if (!(p.first=='0'))
                        for (auto& s : cur) nxt.push_back(p.first + s + p.second);
            }
            cur = nxt;
            oddTurn = !oddTurn;
            if (n >= (int)low.size())
                for (auto& s : cur)
                    if (low <= s && s <= high) ans++;
        }
        return (int)ans;
    }
};

