class Solution:
    def strobogrammaticInRange(self, low: str, high: str) -> int:
        MAP = {'0':'0','1':'1','6':'9','8':'8','9':'6'}

        def cnt_exact(n):
            if n == 1: return 3
            return 4 * 5 ** (n // 2 - 1) * (3 if n % 2 else 1)

        def count_le(x):
            n = len(x)
            total = sum(cnt_exact(i) for i in range(1, n))
            m = n // 2
            for i in range((n + 1) // 2):
                rem = m - i - 1
                ways = (5 ** rem) * (3 if n % 2 else 1)
                lo = 1 if i == 0 else 0
                for d in '01689':
                    dv = int(d)
                    if lo <= dv < int(x[i]):
                        total += ways
                if x[i] not in MAP:
                    return total
            return total + 1

        def is_strobo(s):
            l, r = 0, len(s) - 1
            while l <= r:
                if s[l] not in MAP or MAP[s[l]] != s[r]:
                    return False
                l += 1; r -= 1
            return True

        return count_le(high) - count_le(low) + (1 if is_strobo(low) else 0)

