class Solution {
public:
    long long cntExact(int n) {
        if (n == 1) return 3;
        long long r = 4;
        for (int i = 0; i < n / 2 - 1; i++) r *= 5;
        return r * (n % 2 ? 3 : 1);
    }
    long long countLE(const string& x) {
        int n = x.size();
        long long total = 0;
        for (int i = 1; i < n; i++) total += cntExact(i);
        int m = n / 2;
        string ds = "01689";
        for (int i = 0; i < (n + 1) / 2; i++) {
            long long ways = 1;
            for (int k = 0; k < m - i - 1; k++) ways *= 5;
            if (n % 2) ways *= 3;
            int lo = (i == 0) ? 1 : 0;
            for (char d : ds)
                if (lo <= d - '0' && d - '0' < x[i] - '0') total += ways;
            if (ds.find(x[i]) == string::npos) return total;
        }
        return total + 1;
    }
    bool isStrobo(const string& s) {
        int l = 0, r = s.size() - 1;
        while (l <= r) {
            char m;
            switch (s[l]) {
                case '0': m='0'; break; case '1': m='1'; break;
                case '6': m='9'; break; case '8': m='8'; break;
                case '9': m='6'; break; default: return false;
            }
            if (m != s[r]) return false;
            l++; r--;
        }
        return true;
    }
    int strobogrammaticInRange(string low, string high) {
        long long ans = countLE(high) - countLE(low) + (isStrobo(low) ? 1 : 0);
        return (int) ans;
    }
};

