    const cntExact = n => n === 1 ? 3 : 4 * Math.pow(5, Math.floor(n/2) - 1) * (n % 2 ? 3 : 1);
    const countLE = x => {
        const n = x.length;
        let total = 0;
        for (let i = 1; i < n; i++) total += cntExact(i);
        const m = Math.floor(n / 2);
        const ds = '01689';
        for (let i = 0; i < Math.ceil(n / 2); i++) {
            let ways = Math.pow(5, m - i - 1) * (n % 2 ? 3 : 1);
            const lo = i === 0 ? 1 : 0;
            for (const d of ds)
                if (lo <= +d && +d < +x[i]) total += ways;
            if (!(x[i] in MAP)) return total;
        }
        return total + 1;
    };
    const isStrobo = s => {
        let l = 0, r = s.length - 1;
        while (l <= r) {
            if (!(s[l] in MAP) || MAP[s[l]] !== s[r]) return false;
            l++; r--;
        }
        return true;
    };
    return countLE(high) - countLE(low) + (isStrobo(low) ? 1 : 0);
};
